(function(root){'use strict';
const M=root.BudgetModel||(typeof require==='function'?require('./model.js'):null),copy=x=>JSON.parse(JSON.stringify(x));
const KEYS=['shadeBudgetBasis','installationAllowances','catalog','labor','laborOnsite','currentRate','timezone','materialTax','shippingHandling','fixtureSpacingFt','smallMargin','largeMargin','dayHours','travelBasis','travelBands','driverMax','rangeLowPct','rangeHighPct','keypadCableFtPer','branchRunFt','loadHomeRunFt','networkRunFt','circuitFeedFt','panelFeedFt','panelQsRunFt','linearLeadFt','laborFactors','lineKeypadFeedFt','accessOpeningsPerRoute','newCircuitsPerRoom','shadeLow','shadeHigh','shadeAllowances','shadeReceiversIncluded'];
const REVIEWS=['designReviewed','electricalReviewed','loadCompatibilityReviewed','linearRunsReviewed','qsPowerReviewed','centralCapacityReviewed','networkReviewed','siteConditionsReviewed','shadeScopeReviewed','shadePowerReviewed','shadeMountReviewed'];
function plain(v){if(v&&typeof v==='object'){for(const k of Object.keys(v)){if(['__proto__','prototype','constructor'].includes(k))throw Error('Unsafe object key.');plain(v[k]);}}}
function numeric(v,label){if(v!==null&&(typeof v!=='number'||!Number.isFinite(v)||v<0))throw Error(label+' must be a finite nonnegative number or unset.');}
function date(v){return typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;}
function validate(input){plain(input);if(input?.kind!=='livewire-company-catalog'||input.schemaVersion!==1||input.currency!=='USD'||![9,10,11,12,13].includes(input.modelRevision))throw Error('Unsupported company price-list format. Use the matching Livewire app version.');if(typeof input.catalogVersion!=='string'||!input.catalogVersion.trim()||input.catalogVersion.length>80||!date(input.effectiveAt))throw Error('A version and valid effective date are required.');const cfg={shippingHandling:false,fixtureSpacingFt:0,...input.settings},defaults=M.initial().config;
if(input.modelRevision<12){cfg.shadeBudgetBasis=cfg.shadeBudgetBasis||'historical-range';cfg.installationAllowances={...M.Installation.ALLOWANCES,...cfg.installationAllowances};cfg.labor={...cfg.labor};cfg.laborOnsite={...cfg.laborOnsite};for(const [id,,,hours]of M.Installation.TASKS){if(!(id in cfg.labor))cfg.labor[id]=hours;if(!(id in cfg.laborOnsite))cfg.laborOnsite[id]=true;}}
const compatibleRows=input.modelRevision===9?defaults.catalog.filter(row=>!M.LUMARIS_ADDED_ROWS.includes(row.id)):defaults.catalog;const expectedRows=compatibleRows.filter(row=>!M.ESTATE_ADDED_ROWS.includes(row.id)||(Array.isArray(cfg.catalog)&&cfg.catalog.some(item=>item?.id===row.id)));if(!cfg||!Array.isArray(cfg.catalog)||cfg.catalog.length!==expectedRows.length)throw Error('Catalog must contain every rule for its version exactly once.');const seen=new Set();for(const row of cfg.catalog){if(!row||!expectedRows.some(x=>x.id===row.id)||seen.has(row.id))throw Error('Missing, duplicate or unsupported catalog ID.');seen.add(row.id);if(row.priceBasis!==undefined&&!['catalog','comparable-allowance'].includes(row.priceBasis))throw Error('Invalid price basis for '+row.id);for(const k of ['cost','msrp','pdus'])numeric(row[k],row.id+' '+k);for(const [k,values]of Object.entries({unit:['each','ft','m'],kind:['small','large'],system:['any','none','RA3','HomeWorks'],device:['none','X','A','wired'],pricing:['margin','msrp']}))if(!values.includes(row[k]))throw Error('Invalid '+k+' for '+row.id);for(const k of ['verified','includesPower','includesPlate','includesEnclosure'])if(typeof row[k]!=='boolean')throw Error('Invalid '+k+' for '+row.id);for(const k of ['id','name','sku','source'])if(typeof row[k]!=='string'||row[k].length>3000)throw Error('Invalid catalog text.');}
for(const key of KEYS){if(!(key in cfg))throw Error('Missing company setting '+key);if(key==='catalog')continue;const def=defaults[key],v=cfg[key];if(def&&typeof def==='object'){if(!v||Array.isArray(v)||typeof v!=='object'||Object.keys(v).length!==Object.keys(def).length)throw Error('Invalid '+key);for(const k of Object.keys(def)){if(!(k in v))throw Error('Missing '+key+'.'+k);if(typeof def[k]==='boolean'){if(typeof v[k]!=='boolean')throw Error('Invalid '+key+'.'+k);}else numeric(v[k],key+'.'+k);}}else if(typeof def==='string'){if(typeof v!=='string'||v.length>100)throw Error('Invalid '+key);}else if(typeof def==='boolean'){if(typeof v!=='boolean')throw Error('Invalid '+key);}else if (key==='rangeLowPct'||key==='rangeHighPct'){if(v!==null&&M.budgetAdjustment(v)===null)throw Error(key+' must be at least -100% or unset.');}else numeric(v,key);}
if(!['historical-range','historical-high'].includes(cfg.shadeBudgetBasis))throw Error('Invalid shade budget basis.');
if(Object.values(cfg.installationAllowances).some(v=>v===null||v<=0)||['accessiblePullFactor','extensivePullFactor','tallInstallFactor'].some(k=>cfg.installationAllowances[k]<1))throw Error('Invalid installation method allowances.');
if(cfg.timezone!=='America/New_York'||cfg.travelBasis!=='crew'||cfg.dayHours!==8)throw Error('Unsupported date, time zone or crew-day rule.');for(const k of ['smallMargin','largeMargin'])if(cfg[k]!==null&&cfg[k]>=100)throw Error('Gross margin must be less than 100%.');if(cfg.materialTax!==null&&cfg.materialTax>100)throw Error('Tax percentage exceeds 100%.');if(cfg.rangeLowPct!==null&&cfg.rangeHighPct!==null&&cfg.rangeLowPct>cfg.rangeHighPct)throw Error('Low allowance exceeds high allowance.');const settings=Object.fromEntries(KEYS.map(k=>[k,copy(cfg[k])]));if(input.modelRevision===9)settings.catalog=M.upgradeLumarisCatalog(settings.catalog,defaults.catalog);settings.catalog.push(...defaults.catalog.filter(row=>M.ESTATE_ADDED_ROWS.includes(row.id)&&!seen.has(row.id)));return{kind:input.kind,schemaVersion:1,modelRevision:13,currency:'USD',catalogVersion:input.catalogVersion.trim(),effectiveAt:input.effectiveAt,settings};}
function make(state,version,effectiveAt){const defaults=M.initial().config,settings=Object.fromEntries(KEYS.map(k=>[k,copy(state.config[k])]));settings.catalog=settings.catalog.filter(x=>defaults.catalog.some(d=>d.id===x.id));for(const k of ['labor','laborOnsite','travelBands','driverMax'])settings[k]=Object.fromEntries(Object.keys(defaults[k]).map(id=>[id,settings[k][id]]));return validate({kind:'livewire-company-catalog',schemaVersion:1,modelRevision:13,currency:'USD',catalogVersion:version,effectiveAt,settings});}
function apply(state,input){const p=validate(input),next=copy(state);next.config={...next.config,...copy(p.settings)};for(const k of REVIEWS)next.config[k]=false;next.project.scopeReviewed=false;next.config.roomRoutes={};for(const r of next.rooms)r.routeReviewed=false;next.pricingMeta={version:p.catalogVersion,effectiveAt:p.effectiveAt,draft:false};return next;}
function supplement(state,input){
 const p=validate(input),ids=[...M.RANIA_ADDED_ROWS,'fixture_remodel_rania_fixed','fixture_remodel_rania_adj','fixture_remodel_ketra_fixed','fixture_remodel_ketra_adj'],changed=[];
 for(const id of ids){const row=state.config.catalog.find(x=>x.id===id),fresh=p.settings.catalog.find(x=>x.id===id);
  if(row&&fresh&&row.cost===null&&row.msrp===null&&!row.verified&&fresh.verified){Object.assign(row,copy(fresh));changed.push(id);}
 }
 if(changed.length)state.pricingMeta={...state.pricingMeta,supplement:p.catalogVersion,supplementedIds:changed};
 return changed;
}
function preview(state,input){const next=apply(state,input),before=M.calculate(state),after=M.calculate(next),oldBy=new Map(state.config.catalog.map(x=>[x.id,x]));const changed=next.config.catalog.filter(x=>JSON.stringify(x)!==JSON.stringify(oldBy.get(x.id)));return{next,before,after,changedIds:changed.map(x=>x.id),unpriced:after.materials.filter(x=>x.sell===null).map(x=>x.name)};}
const api={validate,make,apply,supplement,preview,KEYS};root.CompanyPricing=api;if(typeof module!=='undefined')module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
